import pandas as pd
import os

## get rudimentary solver time info from csv generated by get-solver-info script
Z3_RESULTS_DIR = "results-verified/spf-z3/"
ASTR_RESULTS_DIR = "results-verified/spf-astr/"
Z3_new_RESULTS_DIR = "results-verified/new-spf-z3/"
ASTR_new_RESULTS_DIR = "results-verified/new-spf-astr/"

z3 = pd.read_csv(Z3_RESULTS_DIR + "solver-info.csv")
astr = pd.read_csv(ASTR_RESULTS_DIR + "solver-info.csv")
z3_new = pd.read_csv(Z3_new_RESULTS_DIR + "solver-info.csv")
astr_new = pd.read_csv(ASTR_new_RESULTS_DIR + "solver-info.csv")

def get_annoying(df):
    return df[df['bench'] == 'PathUtil']

results1 = pd.merge(z3, astr, on="bench", how="outer", suffixes=('_z3', '_astr'))
results1 = results1[results1["Z3-calls"] > 0]
results2 = pd.merge(z3_new, astr_new, on="bench", how="outer", suffixes=('_z3', '_astr'))
results2 = results2[results2["Z3-calls"] > 0]

results = pd.concat([results1, results2], ignore_index=True)
results = results.astype(int, errors='ignore')

## get the spf recorded timings etc
z3_spf = pd.read_table(Z3_RESULTS_DIR + "spf.results.csv", header=[0,1,2], index_col=0)
astr_spf = pd.read_table(ASTR_RESULTS_DIR + "spf.results.csv", header=[0,1,2], index_col=0)
z3_new_spf = pd.read_table(Z3_new_RESULTS_DIR + "spf.results.csv", header=[0,1,2], index_col=0)
astr_new_spf = pd.read_table(ASTR_new_RESULTS_DIR + "spf.results.csv", header=[0,1,2], index_col=0)

## make them nice for merging
def process_spf_results(spf_df, solver_name):
    spf_df.columns = spf_df.columns.droplevel([0,1])
    spf_df.index = spf_df.index.map(os.path.basename)
    spf_df.index.name = 'bench'
    spf_df = spf_df.reset_index()
    spf_df['bench'] = spf_df['bench'].str.replace('.yml','', regex=False)
    spf_df[f'spf-{solver_name}-cputime (s)'] = spf_df['cputime (s)'].round(2)
    spf_df[f'spf-{solver_name}-walltime (s)'] = spf_df['walltime (s)'].round(2)
    spf_df = spf_df.rename(columns={'status': f'{solver_name}-status'})
    return spf_df[['bench', f'spf-{solver_name}-cputime (s)', f'spf-{solver_name}-walltime (s)', f'{solver_name}-status']]

z3_spf = process_spf_results(z3_spf, 'z3')
z3_new_spf = process_spf_results(z3_new_spf, 'z3')
z3_spf = z3_spf[z3_spf['bench'] != 'PathUtil']
z3_spf = pd.concat([z3_spf, z3_new_spf], ignore_index=True)
astr_spf = process_spf_results(astr_spf, 'astr')
astr_spf = astr_spf[astr_spf['bench'] != 'PathUtil']
astr_new_spf = process_spf_results(astr_new_spf, 'astr')
astr_spf = pd.concat([astr_spf, astr_new_spf], ignore_index=True)
# print(get_annoying(astr_spf))

results = pd.merge(results, z3_spf, on="bench", how="left")
results = pd.merge(results, astr_spf, on="bench", how="left")

## get metadata
def get_log(bench_name, solver_name):
    log_filename = f"SV-COMP26_no-runtime-exception.{bench_name}.yml.log"
    log_path = f"results-verified/{solver_name}/logfiles/{log_filename}"

    if os.path.exists(log_path):
        return log_path
    else:
        return None

def get_bench(bench_name):
    for root, dirs, files in os.walk("sv-benchmarks/java/argv"):
        if os.path.basename(root) == bench_name and "Main.java" in files:
            ret=os.path.join(root, "Main.java")
            return ret
    return None

# def get_source(bench_name):
#     for root, dirs, files, in os.walk("/home/nat/Repos/good-programs"):
#         if f"{bench_name}.java" in files:
#             ret = os.path.join(root, f"{bench_name}.java")

results[['astr-log', 'z3-log', 'benchmark']] = results['bench'].apply(lambda x: pd.Series([get_log(x, 'astr'), get_log(x, 'z3'), get_bench(x)]))

results.to_csv("combined_results.csv", index=False)
